"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[3901],{43901:a=>{a.exports=JSON.parse('{"slug":"yandex-data-centry-ataki-sboi-oblako","locale":"ru","title":"Атаки на 3 дата-центра \xabЯндекса\xbb за 4 дня вывели из строя десятки сервисов","description":"С 8 по 11 октября 2026 года атакованы 3 дата-центра \xabЯндекса\xbb общей мощностью до 115 МВт. Какие сервисы упали и почему восстановление будет дорогим.","blocks":[{"id":"b001","kind":"paragraph","text":"8 октября 2026 года после атаки беспилотника и пожара остановился дата-центр \xabЯндекса\xbb в Сасово Рязанской области, около 12 МВт. 9 октября повреждён дата-центр в Калуге на 63 МВт и больше чем 3800 серверных стоек. 11 октября полностью остановлен дата-центр во Владимире, около 40 МВт. Вместе это до 115 МВт, примерно 6% мощности всех дата-центров России, около 1,8 ГВт. При атаке во Владимире никто не пострадал. Масштаб ущерба \xabЯндекс\xbb не раскрывает и сроки ремонта оборудования не называет."},{"id":"b002","kind":"paragraph","text":"Сбои задели \xabЯндекс Go\xbb, \xabПэй\xbb, \xabПочту\xbb, \xabКарты\xbb и \xabЕду\xbb. Такси не вызывалось и в Казахстане, Беларуси, Армении и Сербии. Упали и чужие сервисы, которые арендуют облако Yandex Cloud: \xabЦиан\xbb, сайты нескольких застройщиков, система электронного документооборота \xabАстрал\xbb. 11 октября \xabЯндекс\xbb сообщил, что сервисы постепенно возвращаются к работе, но 12 октября руководитель финтех-направления Дмитрий Пирогов сказал, что сроки полного восстановления \xabЯндекс Пэй\xbb пока назвать нельзя."},{"id":"b003","kind":"paragraph","text":"Облако это аренда чужих серверов. Компания платит за мощность, а не строит свой дата-центр. Удобно, пока площадка работает. Похоже на семью, у которой все деньги на одной карте одного банка. Карта заблокирована, и платить нечем. Защита от этого: держать копию на другой площадке, это называют резервированием. Оно означает платить за 2 комплекта мощностей вместо 1, поэтому многие на нём экономят. Yandex Cloud делится на зоны, отдельные дата-центры, но из строя вышли 2 зоны из 4, во Владимире и Сасово. Работу оставшихся компания назвала неустойчивой, посоветовала клиентам готовить запасные площадки и договорилась с VK Cloud, Selectel и K2Cloud, что те быстро разместят у себя их данные и сервисы."},{"id":"b004","kind":"paragraph","text":"Восстановление обойдётся дорого. Серверы и ускорители для нейросетей в мире в дефиците из-за спроса на искусственный интеллект. Срок поставки, по оценкам участников рынка, от 2–3 до 6 месяцев. Эльдар Муртазин из Mobile Research Group говорит, что оборудование в России за несколько дней подорожало на 10–15%. Никита Цаплин из RUVDS рассказывает, что часть дата-центров уже усиливает защиту оборудования, и эти расходы, вероятно, попадут в цены для клиентов. Сергей Кудряшов из Strategy Partners оценивает выручку Yandex Cloud примерно в 30 млрд рублей, 2–4% выручки группы. Само облако для \xabЯндекса\xbb небольшой бизнес, но на тех же дата-центрах работают его главные сервисы."},{"id":"b005","kind":"paragraph","text":"Для обычного пользователя сбой означал не работающее такси или оплату. Косвенный путь длиннее. Если облака подорожают из-за дорогого оборудования и защиты, компании, которые их арендуют, переложат часть расходов в цены своих услуг. Насколько, пока никто не оценил."},{"id":"b006","kind":"paragraph","text":"Для бизнеса выбор неприятный. Вторая площадка или переезд к другому провайдеру стоят денег сейчас, хотя оборудование в дефиците. Остаться у одного провайдера дешевле, но следующий сбой снова остановит продажи. Когда \xabЯндекс\xbb вернёт прежние мощности, пока неизвестно."},{"id":"b007","kind":"heading","text":"Какие дата-центры \xabЯндекса\xbb атаковали в октябре 2026 года?"},{"id":"b008","kind":"paragraph","text":"8 октября в Сасово Рязанской области, около 12 МВт, его работа остановлена. 9 октября повреждён дата-центр в Калуге на 63 МВт. 11 октября остановлен дата-центр во Владимире, около 40 МВт."},{"id":"b009","kind":"heading","text":"Какие сервисы не работали из-за атак на дата-центры \xabЯндекса\xbb?"},{"id":"b010","kind":"paragraph","text":"Сбои были у \xabЯндекс Go\xbb, \xabЯндекс Пэй\xbb, \xabПочты\xbb, \xabКарт\xbb, \xabЕды\xbb и у компаний, которые арендуют облако \xabЯндекса\xbb, например \xabЦиана\xbb и \xabАстрала\xbb. Такси не вызывалось и в Казахстане, Беларуси, Армении и Сербии."},{"id":"b011","kind":"heading","text":"Когда восстановят сервисы \xabЯндекса\xbb?"},{"id":"b012","kind":"paragraph","text":"Точных сроков компания не называет. Сервисы постепенно возвращаются, но оборудование для замены поставляют от 2 до 6 месяцев. 12 октября в \xabЯндекс Пэй\xbb сказали, что пока не могут назвать сроки восстановления."}],"sources":[{"label":"Атака на дата-центр \xabЯндекса\xbb вызвала цепную реакцию сбоев. Кто пострадал?","url":"https://thebell.io/ataka-na-data-tsentr-yandeksa-vyzvala-tsepnuyu-reaktsiyu-sboev-kto-postradal"},{"label":"Атаки БПЛА на ЦОД Яндекса вызвали сбои и угрозу роста цен на облака","url":"https://www.kommersant.ru/doc/9024163"},{"label":"Дроны атаковали третий дата-центр \xabЯндекса\xbb за неделю","url":"https://ru.themoscowtimes.com/2026/10/11/droni-atakovali-tretii-data-tsentr-yandeksa-zanedelyu-a208309"},{"label":"Атака БПЛА на дата-центр \xabЯндекса\xbb во Владимире, подробности инцидента","url":"https://www.fontanka.ru/2026/10/11/76693363/"},{"label":"Последствия атак на дата-центры \xabЯндекса\xbb, мнения экспертов","url":"https://www.fontanka.ru/2026/10/11/76693413/"},{"label":"Новый сбой в сервисах Яндекса: дата-центр во Владимире остановлен, зона ru-central1-a недоступна","url":"https://www.comss.ru/page.php?id=22366"},{"label":"В \xabЯндекс Пэй\xbb затруднились назвать сроки восстановления сервиса","url":"https://vz.ru/news/2026/10/12/1461835.html"}],"sourceBodySha256":"90f104461afebdbd416e2a7cbc14c93eb9a1629170e459918558786e22c1b0b1"}')}}]);